import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/AshX.html","title":"AshX","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.51,"words":452},"filePathRelative":"AshX.md"}`),a={name:`AshX.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="ashx" tabindex="-1"><a class="header-anchor" href="#ashx"><span>AshX</span></a></h1><p><a href="./そのうちやりたい事.html">そのうちやりたい事</a></p><p>Android用のシェルっぽいスクリプトが欲しい。とりあえず<a href="./zx.html">zx</a>みたいな何かという事とAndroid Shellをあわせてashxと無付ける。関連ページ: <a href="./小粋なスクリプト言語が欲しい.html">小粋なスクリプト言語が欲しい</a></p><h2 id="リンクメモ" tabindex="-1"><a class="header-anchor" href="#リンクメモ"><span>リンクメモ</span></a></h2><ul><li><a href="./Starlark.html">Starlark</a></li><li><a href="https://plumbum.readthedocs.io/en/latest/" target="_blank" rel="noopener noreferrer">Plumbum</a></li><li><a href="https://github.com/tusharsadhwani/zxpy" target="_blank" rel="noopener noreferrer">zxpy</a></li><li><a href="https://github.com/dsherret/dax" target="_blank" rel="noopener noreferrer">dsherret/dax: Cross-platform shell tools for Deno and Node.js inspired by zx.</a></li><li><a href="https://github.com/amoffat/sh?tab=readme-ov-file" target="_blank" rel="noopener noreferrer">amoffat/sh: Python process launching</a></li><li><a href="https://github.com/denoland/deno/issues/3839" target="_blank" rel="noopener noreferrer">Android support · Issue #3839 · denoland/deno</a> denoは動くのかな？と調べて見つけたチケット。動きそうではある。 <ul><li><a href="https://github.com/denoland/rusty_v8/pull/860" target="_blank" rel="noopener noreferrer">add support for <code>aarch64-linux-android</code> by littledivy · Pull Request #860 · denoland/rusty_v8</a></li></ul></li></ul><h2 id="モチベーション" tabindex="-1"><a class="header-anchor" href="#モチベーション"><span>モチベーション</span></a></h2><p>ちょっとした事をするのにいちいちアプリを作り直すのがかったるい。 例えば現在、<a href="./slog.html">slog</a>にあるようなシェルスクリプトをAndroid上でどうしよう？と思っている。 この目的のためだけにアプリを作るのはかったるい。</p><p>ちょっとした事をするだけのスクリプトを作って、それをランチャーから実行出来るようにしたい。</p><p>大体シェルスクリプトっぽい何かなのだが、runtime permissionとかSAFとかを使える感じの何かにしたい。</p><p><a href="./Starlark.html">Starlark</a>+<a href="https://plumbum.readthedocs.io/en/latest/" target="_blank" rel="noopener noreferrer">Plumbum</a>みたいなシンタックスの何かでどうだろう？</p><p>やりたいのは以下のようなpowershellスクリプトと同じような事。</p><div class="language-powershell line-numbers-mode" data-highlighter="prismjs" data-ext="powershell"><pre><code class="language-powershell"><span class="line"><span class="token variable">$dir</span> = <span class="token function">Split-Path</span> <span class="token variable">$PSCommandPath</span></span>
<span class="line"></span>
<span class="line"><span class="token variable">$items</span> = <span class="token function">Get-ChildItem</span> <span class="token string">&quot;<span class="token variable">$dir</span>&quot;</span> <span class="token operator">-</span><span class="token keyword">Filter</span> <span class="token operator">*</span><span class="token punctuation">.</span>md <span class="token punctuation">|</span> <span class="token function">ForEach-Object</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token variable">$title</span> = <span class="token punctuation">(</span><span class="token function">Get-Content</span> <span class="token variable">$_</span><span class="token punctuation">.</span>FullName <span class="token operator">-</span>TotalCount 1<span class="token punctuation">)</span> <span class="token operator">-replace</span> <span class="token string">&#39;^#\\s*&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span></span>
<span class="line">    <span class="token variable">$date</span>  = <span class="token variable">$_</span><span class="token punctuation">.</span>BaseName <span class="token operator">-replace</span> <span class="token string">&#39;-.*&#39;</span><span class="token punctuation">,</span><span class="token string">&#39;&#39;</span> <span class="token operator">-replace</span> <span class="token string">&#39;_&#39;</span><span class="token punctuation">,</span><span class="token string">&#39; &#39;</span></span>
<span class="line">    <span class="token namespace">[PSCustomObject]</span>@<span class="token punctuation">{</span></span>
<span class="line">        Date  = <span class="token variable">$date</span></span>
<span class="line">        Title = <span class="token variable">$title</span></span>
<span class="line">        Path  = <span class="token variable">$_</span><span class="token punctuation">.</span>FullName</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token variable">$selected</span> = <span class="token variable">$items</span> <span class="token punctuation">|</span> <span class="token function">Out-GridView</span> <span class="token operator">-</span>Title <span class="token string">&quot;Select Markdown&quot;</span> <span class="token operator">-</span>PassThru</span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$selected</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">Start-Process</span> <span class="token variable">$selected</span><span class="token punctuation">.</span>Path</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="コマンドと拡張" tabindex="-1"><a class="header-anchor" href="#コマンドと拡張"><span>コマンドと拡張</span></a></h2><p>コアを作ってコマンドは拡張していける感じに出来たらいいなぁ、と思う。</p><p>とりあえずzxpyのようにチルダでコマンドを実行するとしよう。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">def</span> <span class="token function">mycmd</span><span class="token punctuation">(</span>args<span class="token punctuation">,</span> <span class="token builtin">input</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">   <span class="token keyword">for</span> l <span class="token keyword">in</span> <span class="token builtin">input</span><span class="token punctuation">.</span>as_lines<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token keyword">print</span><span class="token punctuation">(</span>l<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token operator">~</span><span class="token string">&quot;cdt&quot;</span></span>
<span class="line"><span class="token operator">~</span><span class="token string">&quot;ls *.txt | mycmd&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>cdtはSAFのディレクトリ選択。初回はユーザーに選ばせて、二回目以降はpermissionがあるかぎりはそのurlを使う。</p><p>inputはas_lines, as_text, head, tailくらいあればいいか。headとtailはオプショナルなnumの引数つき。</p><p>グローバルスコープの関数はコマンドとして扱う。returnは無しならprint結果を、returnがあれば文字列を次の入力とする。 ストリーミングなどは考えない。</p><p>うーん、これだと既存のコマンドを組み合わせるのがいまいちだな。もうひとひねり欲しいか。</p><h2 id="シェル的なテキストがいるのか" tabindex="-1"><a class="header-anchor" href="#シェル的なテキストがいるのか"><span>シェル的なテキストがいるのか？</span></a></h2><p><a href="https://plumbum.readthedocs.io/en/latest/" target="_blank" rel="noopener noreferrer">Plumbum</a>でも<a href="https://github.com/tusharsadhwani/zxpy" target="_blank" rel="noopener noreferrer">zxpy</a>でも、 基本的にはシェルスクリプトのテキストを生成して実行する。 そのためにはテキストをパースして実行する必要がある。 サブセットでいいので作れば作れるが、本当にテキストを挟む必要があるのか？というのはちょっと納得が行かない所でもある。</p><p>出来たら言語の上でいい感じに書きたい、という気持ちはある。</p><p><a href="https://github.com/amoffat/sh?tab=readme-ov-file" target="_blank" rel="noopener noreferrer">amoffat/sh: Python process launching</a>はテキストに解決しない。 この方がいいのではないか？</p><p>一方で<code>_out</code>引数などを全部のコマンドで処理しないといけないのは何か違うよなぁ。</p><p>やはりStarlarkのようなクラスが無い言語でこういう仕組みを作るのはいまいちな気もする。もう少し良いembed言語がいるか？＞<a href="./EmbeddedLang.html">EmbeddedLang</a></p><p><a href="./Rhino.html">Rhino</a>がいいかもしれない。これでdaxみたいなものを作ればいいのでは？</p><p>daxはshellのパーサーはrustで書かれていて結構でかい。うーん。CommandBuilderを作るDSLが必要なのはそうかもしれんが、そういうのは言語内DSLでどうにかならんのかなぁ。</p><h2 id="jsでやりたい事を書いてみる" tabindex="-1"><a class="header-anchor" href="#jsでやりたい事を書いてみる"><span>JSでやりたい事を書いてみる</span></a></h2><p>とりあえずこんな風に書きたいな、というものをJSっぽい文法で書いてみる。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">cdt</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// SAFでディレクトリを選ぶ</span></span>
<span class="line"><span class="token keyword">let</span> res <span class="token operator">=</span> <span class="token function">ls</span><span class="token punctuation">(</span><span class="token string">&quot;*.md&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token parameter">f</span><span class="token operator">=&gt;</span><span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">let</span> title <span class="token operator">=</span> <span class="token function">head</span><span class="token punctuation">(</span>f<span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token literal-property property">n</span><span class="token operator">:</span><span class="token number">1</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token string">&quot;^#¥s*&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">let</span> date <span class="token operator">=</span> <span class="token function">basename</span><span class="token punctuation">(</span>f<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token string">&quot;-.*&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token string">&quot;_&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">)</span></span>
<span class="line">           <span class="token punctuation">[</span>title<span class="token punctuation">,</span> date<span class="token punctuation">,</span> f<span class="token punctuation">]</span></span>
<span class="line">         <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">         <span class="token punctuation">.</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>res<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">open</span><span class="token punctuation">(</span>res<span class="token punctuation">.</span>path<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>こんな感じで書けたらいいな。 ただこれだとストリーミングはされないだろうな。そしてエラーもうまく扱えないな。</p><p>でもまずは簡潔な記述だよな。こんな感じで書ければ使ってもいい気はする。</p><h2 id="開発メモ" tabindex="-1"><a class="header-anchor" href="#開発メモ"><span>開発メモ</span></a></h2><ul><li><a href="https://github.com/mozilla/rhino/blob/master/examples/src/main/java/Shell.java" target="_blank" rel="noopener noreferrer">rhino/examples/src/main/java/Shell.java at master · mozilla/rhino</a></li><li><a href="https://github.com/mozilla/rhino/blob/master/rhino-tools/src/main/java/org/mozilla/javascript/tools/shell/Global.java" target="_blank" rel="noopener noreferrer">rhino/rhino-tools/src/main/java/org/mozilla/javascript/tools/shell/Global.java at master · mozilla/rhino</a></li><li><a href="https://rhino.github.io/docs/scopes_and_contexts/" target="_blank" rel="noopener noreferrer">Scopes and contexts - Rhino</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Generator" target="_blank" rel="noopener noreferrer">Generator - JavaScript - MDN</a></li></ul><h3 id="とりあえずreplが動くまで-2026-03-20-金" tabindex="-1"><a class="header-anchor" href="#とりあえずreplが動くまで-2026-03-20-金"><span>とりあえずreplが動くまで 2026-03-20 (金)</span></a></h3><p>ExamplesのShell.javaを参考にJetpack Composeで雑に書いた上側に入力、下側にコンソール、という構成で、とりあえずprintとclearだけ追加したもので実行出来るまでは出来た。<a href="./Rhino.html">Rhino</a>は有能だな。</p><p>次はcdtとlsを作りたいな。</p>`,38)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};